package vmcompat;
import java.nio.*;import java.nio.file.*;import java.util.*;
import org.lwjgl.opengl.*;import org.joml.Matrix4f;import viewpoint.render.FrameContext;
import static vmcompat.Counters.Key.*;
/** Original single-outstanding-request protocol. Timers add no waits/readbacks. */
public final class Picking {
    private static final class Local {long mark,beginNano,calls,nextCall;boolean collecting,afterRead,staged;FrameContext context;Matrix4f inverse;Request pending;long requests;}
    private static final StateStore<Local> LOCAL=new StateStore<>(Local::new);
    private static final class Request {long id,frame,snapshot,thread,issuedCall,collectedCall,ageCalls,contextGeneration,depthGeneration,depthVersion,pboGeneration,issued,age,latency;int x,y,source,pbo,depth,width,height,format;float value;float[] inverse,eye;double[] origin;String state="issued";}
    private static final ArrayDeque<Request> RECENT=new ArrayDeque<>();
    private static final long[] LATENCIES=new long[4096],AGES=new long[4096];private static long latencyCount;
    private static long requests,results,notReady,calls,rateSkips;private static final int LIMIT=32;
    public static void begin(FrameContext context,int fbo,Matrix4f inverse){Local s=LOCAL.get();s.calls++;Counters.add(PICK_CALLS,1);if(Counters.ENABLED)synchronized(Picking.class){calls++;}s.beginNano=System.nanoTime();s.context=context;s.inverse=inverse;s.afterRead=false;s.staged=false;s.mark=Counters.now();}
    /** Called only after the original Ask/size/fence eligibility checks. */
    public static boolean allowRequest(){Local s=LOCAL.get();if(s.calls>=s.nextCall)return true;Counters.add(PICK_RATE_SKIPS,1);if(Counters.ENABLED)synchronized(Picking.class){rateSkips++;}return false;}
    private static void preparation(Local s){if(s.mark!=0)Counters.elapsed(PICK_PREPARE_NS,s.mark);s.mark=0;}
    public static void end(){HangTrace.step("idle");NativePickBoundary.end();Local s=LOCAL.get();preparation(s);s.context=null;s.inverse=null;}
    public static void bindFramebuffer(int target,int fbo){Local s=LOCAL.get();preparation(s);long at=Counters.now();GL30.glBindFramebuffer(target,fbo);Counters.elapsed(s.afterRead?PICK_RESTORE_NS:PICK_STATE_NS,at);Counters.add(PICK_BIND_CALLS,1);s.mark=Counters.now();}
    public static void bindBuffer(int target,int buffer){Local s=LOCAL.get();preparation(s);long at=Counters.now();GL15.glBindBuffer(target,buffer);Counters.elapsed(s.afterRead?PICK_RESTORE_NS:PICK_STATE_NS,at);Counters.add(PICK_BIND_CALLS,1);s.mark=Counters.now();}
    public static void allocate(int target,long size,int usage){Local s=LOCAL.get();preparation(s);long at=Counters.now();try{Buffers.glBufferData(target,size,usage);}finally{Counters.elapsed(PICK_BUFFER_ALLOC_NS,at);s.mark=Counters.now();}}
    public static void readPixels(int x,int y,int w,int h,int format,int type,long offset){
        Local s=LOCAL.get();preparation(s);Request r=null;
        if(Options.PICK_DETAIL&&Counters.ENABLED){long metaAt=Counters.now();r=new Request();r.id=++s.requests;r.issuedCall=s.calls;r.frame=Telemetry.displayId()+1;r.snapshot=0;r.thread=Thread.currentThread().threadId();r.contextGeneration=ContextResources.current().generation();r.x=x;r.y=y;if(s.context!=null){r.eye=new float[]{s.context.eyeX,s.context.eyeY,s.context.eyeZ};if(s.context.scene!=null)r.origin=new double[]{s.context.scene.originX,s.context.scene.originY,s.context.scene.originZ};}r.source=GL11.glGetInteger(GL30.GL_READ_FRAMEBUFFER_BINDING);r.pbo=GL11.glGetInteger(GL21.GL_PIXEL_PACK_BUFFER_BINDING);if(r.pbo!=0)r.pboGeneration=Buffers.identity(r.pbo)[0];if(s.inverse!=null)r.inverse=s.inverse.get(new float[16]);describe(r);if(NativePickBoundary.staged()){var n=NativePickBoundary.STATES.get();r.x=n.x;r.y=n.y;r.source=n.read;r.depth=n.texture;r.depthGeneration=Buffers.textureLifetime(r.depth);r.depthVersion=Textures.pixelVersion(r.depth);var image=Textures.description(r.depth);if(image!=null){r.width=image.width();r.height=image.height();r.format=image.format();}}r.issued=s.beginNano==0?System.nanoTime():s.beginNano;Counters.elapsed(PICK_STATE_NS,metaAt);}
        long at=Counters.now();boolean staged=NativePickBoundary.staged();
        try{if(Options.PICKING.equals("depthStaging")&&w==1&&h==1&&format==GL11.GL_DEPTH_COMPONENT&&type==GL11.GL_FLOAT)staged=DepthStaging.read(x,y,offset);if(!staged||NativePickBoundary.staged())nativeRead(x,y,w,h,format,type,offset);Buffers.pixelPackWrite();}
        finally{Counters.elapsed(PICK_READ_PIXELS_NS,at);Counters.add(staged?PICK_STAGED:PICK_ORIGINAL,1);s.mark=Counters.now();s.afterRead=true;s.staged=staged;}
        s.nextCall=s.calls+Options.PICK_EVERY;
        if(r!=null){s.pending=r;synchronized(Picking.class){requests++;RECENT.addLast(r);if(RECENT.size()>LIMIT)RECENT.removeFirst();}}Counters.add(PICK_REQUESTS,1);
    }
    public static void nativeRead(int x,int y,int w,int h,int format,int type,long offset){HangTrace.step("picking-read");long at=Counters.now();try{GL11.glReadPixels(x,y,w,h,format,type,offset);}finally{Counters.elapsed(PICK_NATIVE_READ_PIXELS_NS,at);Counters.add(PICK_NATIVE_READS,1);}}
    private static void describe(Request r){if(r.source==0)return;int kind=GL30.glGetFramebufferAttachmentParameteri(GL30.GL_READ_FRAMEBUFFER,GL30.GL_DEPTH_ATTACHMENT,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE);if(kind!=GL11.GL_TEXTURE)return;
        r.depth=GL30.glGetFramebufferAttachmentParameteri(GL30.GL_READ_FRAMEBUFFER,GL30.GL_DEPTH_ATTACHMENT,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME);r.depthGeneration=Buffers.textureLifetime(r.depth);r.depthVersion=Textures.pixelVersion(r.depth);Textures.Image image=Textures.description(r.depth);if(image!=null){r.width=image.width();r.height=image.height();r.format=image.format();}}
    public static long fence(int condition,int flags){Local s=LOCAL.get();preparation(s);long at=Counters.now();try{long f=GL32.glFenceSync(condition,flags);if(s.staged&&Options.PICK_EARLY){long flush=Counters.now();GL11.glFlush();Counters.elapsed(PICK_FLUSH_NS,flush);}return f;}finally{Counters.elapsed(PICK_FENCE_NS,at);Counters.add(PICK_FENCES,1);s.mark=Counters.now();}}
    public static int poll(long fence,int flags,long timeout){Local s=LOCAL.get();preparation(s);long at=Counters.now();int result;try{result=GL32.glClientWaitSync(fence,flags,timeout);}finally{Counters.elapsed(PICK_POLL_NS,at);s.mark=Counters.now();}boolean ready=result==GL32.GL_ALREADY_SIGNALED||result==GL32.GL_CONDITION_SATISFIED;Counters.add(ready?PICK_READY:PICK_NOT_READY,1);synchronized(Picking.class){if(!ready)notReady++;if(s.pending!=null)s.pending.state=ready?"ready":"pending";}return result;}
    public static void collect(int target,long offset,FloatBuffer out){Local s=LOCAL.get();preparation(s);long at=Counters.now();try{GL15.glGetBufferSubData(target,offset,out);}finally{Counters.elapsed(PICK_COLLECT_BYTES_NS,at);s.mark=Counters.now();}Counters.add(PICK_RESULTS,1);Request r=s.pending;if(r!=null){synchronized(Picking.class){r.collectedCall=s.calls;r.ageCalls=Math.max(0,r.collectedCall-r.issuedCall);r.age=Math.max(0,Telemetry.displayId()+1-r.frame);r.latency=System.nanoTime()-r.issued;r.value=out.get(out.position());r.state="collected";results++;int slot=(int)(latencyCount++%LATENCIES.length);LATENCIES[slot]=r.latency;AGES[slot]=r.age;}Counters.add(PICK_AGE_FRAMES,r.age);Counters.add(PICK_AGE_CALLS,r.ageCalls);Counters.add(PICK_LATENCY_NS,r.latency);s.pending=null;}}
    public record Latency(int samples,long p95Ns,long p99Ns,long maxNs,double meanAge,long maxAge){}
    public static synchronized Latency latency(){int n=(int)Math.min(latencyCount,LATENCIES.length);if(n==0)return new Latency(0,0,0,0,0,0);long[] values=Arrays.copyOf(LATENCIES,n);Arrays.sort(values);long age=0,maxAge=0;for(int i=0;i<n;i++){age+=AGES[i];maxAge=Math.max(maxAge,AGES[i]);}return new Latency(n,values[(int)Math.ceil(n*.95)-1],values[(int)Math.ceil(n*.99)-1],values[n-1],(double)age/n,maxAge);}
    static synchronized void snapshot(long id){long frame=Telemetry.displayId()+1,thread=Thread.currentThread().threadId();for(Request r:RECENT)if(r.snapshot==0&&r.frame==frame&&r.thread==thread)r.snapshot=id;}
    static void write(Path path)throws Exception{String text;synchronized(Picking.class){StringJoiner entries=new StringJoiner(",");for(Request r:RECENT){String matrix=r.inverse==null?"null":Arrays.toString(r.inverse);String origin=r.origin==null?"null":Arrays.toString(r.origin),eye=r.eye==null?"null":Arrays.toString(r.eye);entries.add("{\"request_id\":"+r.id+",\"issued_picking_call\":"+r.issuedCall+",\"collected_picking_call\":"+r.collectedCall+",\"age_picking_calls\":"+r.ageCalls+",\"age_ms\":"+(r.latency/1e6)+",\"display_id\":"+r.frame+",\"snapshot_id\":"+r.snapshot+",\"context_generation\":"+r.contextGeneration+",\"eye\":"+eye+",\"origin\":"+origin+",\"source_fbo\":"+r.source+",\"depth_texture\":"+r.depth+",\"depth_generation\":"+r.depthGeneration+",\"depth_version\":"+r.depthVersion+",\"width\":"+r.width+",\"height\":"+r.height+",\"format\":"+r.format+",\"x\":"+r.x+",\"y\":"+r.y+",\"pbo\":"+r.pbo+",\"pbo_generation\":"+r.pboGeneration+",\"state\":\""+r.state+"\",\"age_intervals\":"+r.age+",\"latency_ns\":"+r.latency+",\"depth\":"+(Float.isFinite(r.value)?r.value:0)+",\"inverse\":"+matrix+"}");}Latency timing=latency();text="{\"latency_window_samples\":"+timing.samples()+",\"latency_p95_ns\":"+timing.p95Ns()+",\"latency_p99_ns\":"+timing.p99Ns()+",\"mean_age_intervals\":"+timing.meanAge()+",\"max_age_intervals\":"+timing.maxAge()+",\"schema\":2,\"pickEvery\":"+Options.PICK_EVERY+",\"picking_calls\":"+calls+",\"rate_skips\":"+rateSkips+",\"limit\":32,\"requests\":"+requests+",\"results\":"+results+",\"not_ready_polls\":"+notReady+",\"recent\":["+entries+"]}\n";}Path tmp=path.resolveSibling(path.getFileName()+".tmp");Files.writeString(tmp,text);try{Files.move(tmp,path,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,path,StandardCopyOption.REPLACE_EXISTING);}}
}
